// Turn a Telegram message into a ticker. Accepts /ta AAPL, $TSLA or a bare ticker; /start or /help shows usage.
const s = $('Set bot settings').first().json;
const msg = $('Receive Telegram message').first().json.message || {};
const raw = String(msg.text || '').trim();
const ALIAS = { BTC: 'BTC-USD', ETH: 'ETH-USD', SOL: 'SOL-USD', SPX: '^GSPC', SP500: '^GSPC', NASDAQ: '^IXIC', FTSE: '^FTSE', GOLD: 'GC=F' };
const words = raw.replace(/^\/(\w+)@\w+/, '/$1').split(/\s+/).filter(Boolean);
const first = (words[0] || '').toLowerCase();
const args = first.startsWith('/') ? words.slice(1) : words;
let t = (args[0] || '').replace(/^\$/, '').toUpperCase();
t = ALIAS[t] || t;
const ok = !['/start', '/help'].includes(first) && /^[A-Z0-9.^=\-]{1,15}$/.test(t);
return [{ json: { action: ok ? 'analyze' : 'help', chat_id: String(msg.chat?.id ?? ''), tickers: ok ? [t] : [],
  range: s.default_range || '1y', raw } }];

// Technical indicators computed from Yahoo Finance daily candles. Pure maths: the AI only explains these numbers.
const PRO = false;
const src = $('Prepare ticker').all();
const round = (x, d = 2) => (x === null || x === undefined || !isFinite(x)) ? null : Math.round(x * 10 ** d) / 10 ** d;
const sma = (a, n) => a.map((_, i) => i < n - 1 ? null : a.slice(i - n + 1, i + 1).reduce((s, v) => s + v, 0) / n);
const ema = (a, n) => { const k = 2 / (n + 1); let e = null; return a.map((v, i) => {
  if (i < n - 1) return null; if (e === null) { e = a.slice(0, n).reduce((s, x) => s + x, 0) / n; return e; }
  e = v * k + e * (1 - k); return e; }); };
function rsi(a, n = 14) {               // Wilder's smoothing
  const out = a.map(() => null); let g = 0, l = 0;
  for (let i = 1; i < a.length; i++) {
    const d = a[i] - a[i - 1], up = Math.max(d, 0), dn = Math.max(-d, 0);
    if (i <= n) { g += up; l += dn; if (i === n) { g /= n; l /= n; out[i] = l === 0 ? 100 : 100 - 100 / (1 + g / l); } }
    else { g = (g * (n - 1) + up) / n; l = (l * (n - 1) + dn) / n; out[i] = l === 0 ? 100 : 100 - 100 / (1 + g / l); }
  }
  return out;
}
function pivots(hi, lo, w = 5) {        // swing highs / lows
  const res = [];
  for (let i = w; i < hi.length - w; i++) {
    const h = hi.slice(i - w, i + w + 1), l = lo.slice(i - w, i + w + 1);
    if (hi[i] === Math.max(...h)) res.push(hi[i]);
    if (lo[i] === Math.min(...l)) res.push(lo[i]);
  }
  return res;
}
function levels(points, price, tol) {   // cluster pivots into zones, count touches
  const zones = [];
  for (const p of points.sort((a, b) => a - b)) {
    const z = zones.find(z => Math.abs(z.level - p) <= tol);
    if (z) { z.sum += p; z.n += 1; z.level = z.sum / z.n; } else zones.push({ level: p, sum: p, n: 1 });
  }
  const below = zones.filter(z => z.level < price).sort((a, b) => b.level - a.level);
  const above = zones.filter(z => z.level > price).sort((a, b) => a.level - b.level);
  return { support: below.slice(0, 2).map(z => ({ level: round(z.level), touches: z.n })),
           resistance: above.slice(0, 2).map(z => ({ level: round(z.level), touches: z.n })) };
}
const ago = n => n === 0 ? 'today' : n === 1 ? 'yesterday' : `${n} days ago`;
const out = [];
$input.all().forEach((item, i) => {
  const req = src[i]?.json || {};
  const symbol = req.symbol || '?';
  const body = item.json || {};
  const res = body.chart?.result?.[0];
  const err = body.chart?.error?.description || body.error?.message || (typeof body.error === 'string' ? body.error : '');
  if (!res || !res.timestamp) {
    out.push({ json: { ok: false, symbol, chat_id: req.chat_id, problem: err ? `Yahoo Finance: ${err}` :
      `No price data for ${symbol}. Check the ticker (US: AAPL, London: VOD.L, crypto: BTC-USD, index: ^GSPC).` } });
    return;
  }
  const q = res.indicators?.quote?.[0] || {};
  const rows = res.timestamp.map((t, k) => ({ t, o: q.open?.[k], h: q.high?.[k], l: q.low?.[k], c: q.close?.[k], v: q.volume?.[k] }))
    .filter(r => [r.o, r.h, r.l, r.c].every(x => typeof x === 'number' && isFinite(x)));
  if (rows.length < 35) {
    out.push({ json: { ok: false, symbol, chat_id: req.chat_id, problem: `Only ${rows.length} trading days of data for ${symbol}; need at least 35.` } });
    return;
  }
  const c = rows.map(r => r.c), hi = rows.map(r => r.h), lo = rows.map(r => r.l), vol = rows.map(r => r.v || 0);
  const last = rows.length - 1, price = c[last], prev = c[last - 1];
  const s20 = sma(c, 20), s50 = sma(c, 50), s200 = sma(c, 200), e20 = ema(c, 20);
  const r14 = rsi(c, 14);
  const e12 = ema(c, 12), e26 = ema(c, 26);
  const macd = c.map((_, k) => e12[k] !== null && e26[k] !== null ? e12[k] - e26[k] : null);
  const mv = macd.filter(x => x !== null), sigRaw = ema(mv, 9);
  const signal = macd.map((_, k) => { const j = k - (macd.length - mv.length); return j >= 0 ? sigRaw[j] : null; });
  const hist = macd.map((m, k) => m !== null && signal[k] !== null ? m - signal[k] : null);
  const signals = [];
  let bias = 0;
  // Trend
  const above50 = s50[last] !== null ? price > s50[last] : null, above200 = s200[last] !== null ? price > s200[last] : null;
  if (above50 !== null) bias += above50 ? 15 : -15;
  if (above200 !== null) bias += above200 ? 20 : -20;
  let trend = 'sideways';
  if (above50 && (above200 ?? true) && s20[last] > (s50[last] ?? 0)) trend = 'uptrend';
  else if (above50 === false && !(above200 ?? false) && s20[last] < (s50[last] ?? Infinity)) trend = 'downtrend';
  for (let k = Math.max(1, last - 9); k <= last; k++) {
    if ([s50[k], s200[k], s50[k - 1], s200[k - 1]].some(x => x === null)) continue;
    if (s50[k - 1] <= s200[k - 1] && s50[k] > s200[k]) signals.push(`Golden cross (50-day above 200-day) ${ago(last - k)}`);
    if (s50[k - 1] >= s200[k - 1] && s50[k] < s200[k]) signals.push(`Death cross (50-day below 200-day) ${ago(last - k)}`);
  }
  // Momentum
  const rNow = r14[last], rPrev = r14[last - 1];
  if (rNow !== null) {
    if (rNow >= 70) { signals.push(`RSI ${round(rNow, 0)}: overbought zone`); bias -= 10; }
    else if (rNow <= 30) { signals.push(`RSI ${round(rNow, 0)}: oversold zone`); bias += 10; }
    else bias += (rNow - 50) / 2;
    if (rPrev !== null && rPrev < 30 && rNow >= 30) signals.push('RSI moved back above 30');
    if (rPrev !== null && rPrev > 70 && rNow <= 70) signals.push('RSI dropped back below 70');
  }
  for (let k = Math.max(1, last - 2); k <= last; k++) {
    if (hist[k] === null || hist[k - 1] === null) continue;
    if (hist[k - 1] <= 0 && hist[k] > 0) { signals.push(`MACD crossed above its signal line ${ago(last - k)}`); bias += 10; }
    if (hist[k - 1] >= 0 && hist[k] < 0) { signals.push(`MACD crossed below its signal line ${ago(last - k)}`); bias -= 10; }
  }
  if (hist[last] !== null) bias += hist[last] > 0 ? 5 : -5;
  const ind = {
    price: round(price), change_pct: round((price / prev - 1) * 100), as_of: new Date(rows[last].t * 1000).toISOString().slice(0, 10),
    sma20: round(s20[last]), sma50: round(s50[last]), sma200: round(s200[last]), ema20: round(e20[last]),
    rsi14: round(rNow, 1), macd: round(macd[last], 3), macd_signal: round(signal[last], 3), macd_hist: round(hist[last], 3),
  };
  let lv = { support: [], resistance: [] }, chartExtra = {};
  if (PRO) {
    const sd = c.map((_, k) => k < 19 ? null : Math.sqrt(c.slice(k - 19, k + 1).reduce((s, v) => s + (v - s20[k]) ** 2, 0) / 20));
    const bbU = s20.map((m, k) => m === null ? null : m + 2 * sd[k]), bbL = s20.map((m, k) => m === null ? null : m - 2 * sd[k]);
    const tr = rows.map((r, k) => k === 0 ? r.h - r.l : Math.max(r.h - r.l, Math.abs(r.h - c[k - 1]), Math.abs(r.l - c[k - 1])));
    const atr = sma(tr, 14);
    const width = s20.map((m, k) => m ? (bbU[k] - bbL[k]) / m : null);
    const recentW = width.slice(-120).filter(x => x !== null);
    const vAvg = sma(vol, 20);
    const yr = rows.slice(-252);
    const hi52 = Math.max(...yr.map(r => r.h)), lo52 = Math.min(...yr.map(r => r.l));
    lv = levels(pivots(hi.slice(-150), lo.slice(-150)), price, (atr[last] || price * 0.01) * 0.75);
    Object.assign(ind, { bb_upper: round(bbU[last]), bb_lower: round(bbL[last]), atr14: round(atr[last]),
      atr_pct: round(atr[last] / price * 100), volume_vs_20d: vAvg[last] ? round(vol[last] / vAvg[last]) : null,
      high_52w: round(hi52), low_52w: round(lo52), from_52w_high_pct: round((price / hi52 - 1) * 100),
      support: lv.support, resistance: lv.resistance });
    if (bbU[last] !== null && price > bbU[last]) signals.push('Closed above the upper Bollinger Band (stretched)');
    if (bbL[last] !== null && price < bbL[last]) signals.push('Closed below the lower Bollinger Band (stretched)');
    if (recentW.length > 60 && width[last] !== null && width[last] <= Math.min(...recentW) * 1.05) signals.push('Bollinger squeeze: volatility at a 6-month low');
    if (ind.volume_vs_20d && ind.volume_vs_20d >= 2) signals.push(`Volume ${ind.volume_vs_20d}x its 20-day average`);  // today's bar can be partial during market hours
    if (lv.resistance[0] && prev < lv.resistance[0].level && price >= lv.resistance[0].level) signals.push(`Broke above resistance near ${lv.resistance[0].level}`);
    const brokeSup = levels(pivots(hi.slice(-151, -1), lo.slice(-151, -1)), prev, (atr[last] || price * 0.01) * 0.75).support[0];
    if (brokeSup && price < brokeSup.level) signals.push(`Fell below support near ${brokeSup.level}`);
    if (ind.from_52w_high_pct !== null && ind.from_52w_high_pct >= -1) signals.push('Trading at or near its 52-week high');
    if (price <= lo52 * 1.01) signals.push('Trading at or near its 52-week low');
    chartExtra = { bbU, bbL };
  }
  bias = Math.max(-100, Math.min(100, Math.round(bias)));
  const label = bias >= 25 ? 'bullish' : bias <= -25 ? 'bearish' : 'neutral';
  // Chart window = the requested range (2 years are always fetched so the 200-day average exists)
  const BARS = { '3mo': 63, '6mo': 126, '1y': 252, '2y': 504, '5y': 1260 };
  const N = Math.min(BARS[req.range] || 252, rows.length), from = rows.length - N;
  const step = Math.ceil(N / 240);                     // QuickChart's free tier allows about 250 points per line
  const idx = []; for (let k = last; k >= from; k -= step) idx.unshift(k);
  const cut = a => idx.map(k => a[k] === null || a[k] === undefined ? null : round(a[k]));
  const datasets = [
    { label: symbol, data: cut(c), borderColor: '#1f6feb', borderWidth: 2, pointRadius: 0, fill: false },
    { label: 'SMA 20', data: cut(s20), borderColor: '#f59e0b', borderWidth: 1.5, pointRadius: 0, fill: false },
    { label: 'SMA 50', data: cut(s50), borderColor: '#8b5cf6', borderWidth: 1.5, pointRadius: 0, fill: false },
  ];
  if (s200[last] !== null) datasets.push({ label: 'SMA 200', data: cut(s200), borderColor: '#111827', borderWidth: 1.5, pointRadius: 0, fill: false });
  if (PRO) {
    datasets.push({ label: 'BB upper', data: cut(chartExtra.bbU), borderColor: '#9ca3af', borderDash: [4, 4], borderWidth: 1, pointRadius: 0, fill: false });
    datasets.push({ label: 'BB lower', data: cut(chartExtra.bbL), borderColor: '#9ca3af', borderDash: [4, 4], borderWidth: 1, pointRadius: 0, fill: false });
    lv.support.slice(0, 1).forEach(z => datasets.push({ label: `Support ${z.level}`, data: Array(idx.length).fill(z.level), borderColor: '#16a34a', borderDash: [8, 4], borderWidth: 1.5, pointRadius: 0, fill: false }));
    lv.resistance.slice(0, 1).forEach(z => datasets.push({ label: `Resistance ${z.level}`, data: Array(idx.length).fill(z.level), borderColor: '#dc2626', borderDash: [8, 4], borderWidth: 1.5, pointRadius: 0, fill: false }));
  }
  const labels = idx.map(k => new Date(rows[k].t * 1000).toISOString().slice(N > 300 ? 2 : 5, N > 300 ? 7 : 10));
  const name = String(res.meta?.shortName || res.meta?.longName || symbol).replace(/\s+/g, ' ').trim();
  const chart = { version: '4', backgroundColor: '#ffffff', width: 900, height: 500, format: 'png',
    chart: { type: 'line', data: { labels, datasets },
      options: { plugins: { title: { display: true, text: `${name} (${symbol}) · ${res.meta?.currency || ''} ${ind.price} · RSI ${ind.rsi14 ?? '-'} · MACD ${hist[last] > 0 ? 'above' : 'below'} signal` },
        legend: { labels: { boxWidth: 12 } } },
        scales: { x: { ticks: { maxTicksLimit: 12 } } } } } };
  out.push({ json: { ok: true, symbol, name, currency: res.meta?.currency || '', exchange: res.meta?.fullExchangeName || res.meta?.exchangeName || '',
    chat_id: req.chat_id, range: req.range, trend, bias_score: bias, bias: label, signals, indicators: ind, chart } });
});
return out;

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// One Telegram report per ticker: short chart caption + full analysis. Falls back to the numbers if the AI step failed.
const comp = $('Compute indicators').all().filter(x => x.json.ok);
const charts = $('Draw chart with QuickChart').all();
const DISC = 'Not financial advice. Educational technical analysis of delayed market data; do your own research.';
return $input.all().map((item, i) => {
  const d = comp[i]?.json || {};
  const ai = item.json.output || {};
  const ind = d.indicators || {};
  const fmt = v => v === null || v === undefined ? '-' : v;
  const arrow = ind.change_pct > 0 ? '▲' : ind.change_pct < 0 ? '▼' : '•';
  const icon = { bullish: '🟢', bearish: '🔴', neutral: '🟡' }[d.bias] || '⚪';
  const lines = [`<b>${esc(d.name)} (${esc(d.symbol)})</b> ${esc(d.currency)} ${fmt(ind.price)} ${arrow} ${fmt(ind.change_pct)}%`,
    `${icon} Technical bias: <b>${esc(d.bias)}</b> (${d.bias_score}) · ${esc(d.trend)}`,
    ai.headline ? `<i>${esc(ai.headline)}</i>` : ''];
  const caption = (lines.filter(Boolean).join('\n') + `\n\n⚠️ ${DISC}`).slice(0, 1000);
  const nums = [`RSI(14) ${fmt(ind.rsi14)} · MACD hist ${fmt(ind.macd_hist)}`,
    `SMA20 ${fmt(ind.sma20)} · SMA50 ${fmt(ind.sma50)} · SMA200 ${fmt(ind.sma200)} · EMA20 ${fmt(ind.ema20)}`];
  if (ind.bb_upper !== undefined) nums.push(`Bollinger ${fmt(ind.bb_lower)}–${fmt(ind.bb_upper)} · ATR ${fmt(ind.atr14)} (${fmt(ind.atr_pct)}%/day)`);
  if (ind.support) nums.push(`Support ${(ind.support || []).map(z => z.level).join(', ') || '-'} · Resistance ${(ind.resistance || []).map(z => z.level).join(', ') || '-'}`);
  if (ind.high_52w !== undefined) nums.push(`52w range ${fmt(ind.low_52w)}–${fmt(ind.high_52w)} (${fmt(ind.from_52w_high_pct)}% from high)`);
  const body = ai.trend ? [`📈 <b>Trend</b>: ${esc(ai.trend)}`, `⚡ <b>Momentum</b>: ${esc(ai.momentum)}`, `🧱 <b>Levels</b>: ${esc(ai.levels)}`,
    `👀 <b>What to watch</b>: ${esc(ai.watch)}`, ai.risk ? `🎢 <b>Volatility</b>: ${esc(ai.risk)}` : ''].filter(Boolean).join('\n')
    : '<i>(AI summary unavailable this time; numbers below are computed directly from the price data.)</i>';
  const sig = (d.signals || []).length ? '\n\n🔔 <b>Signals</b>\n' + d.signals.map(s => '• ' + esc(s)).join('\n') : '';
  const text = `${lines.filter(Boolean).join('\n')}\n\n${body}${sig}\n\n<code>${esc(nums.join('\n'))}</code>\n\nData: Yahoo Finance daily candles to ${esc(ind.as_of)}.\n⚠️ ${DISC}`;
  const bin = charts[i]?.binary;
  return { json: { symbol: d.symbol, chat_id: d.chat_id, caption, text: text.slice(0, 4000), has_chart: !!(bin && bin.data) }, ...(bin && bin.data ? { binary: bin } : {}) };
});
